// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address user, uint256 deposit1, uint256 deposit2) public {
        vm.assume(user != address(0) && user != address(this));
        vm.assume(deposit1 <= 1e36 && deposit2 <= 1e36);
        vm.assume(deposit1 + deposit2 >= deposit1);

        uint256 sum = deposit1 + deposit2;

        vm.deal(user, sum);
        vm.startPrank(user);
        c.addToBalance{value: deposit1}();
        c.addToBalance{value: deposit2}();
        vm.stopPrank();

        uint256 recorded = c.getBalance(user);
        assertEq(recorded, sum, "balance must equal sum of deposits");
    }
}
